1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	    <meta charset="UTF-8">
5	    <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	    <meta name="description" content="A modern, accessible website built with best practices">
7	    <meta name="theme-color" content="#667eea">
8	    <meta property="og:title" content="Modern Web Template">
9	    <meta property="og:description" content="A modern, accessible website built with best practices">
10	    <meta property="og:type" content="website">
11	    <title>Welcome | Modern Web Template</title>
12	    <style>
13	        * {
14	            margin: 0;
15	            padding: 0;
16	            box-sizing: border-box;
17	        }
18	
19	        body {
20	            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
21	            line-height: 1.6;
22	            background-color: #f8f9fa;
23	            color: #2c3e50;
24	        }
25	
26	        a:focus-visible {
27	            outline: 3px solid #667eea;
28	            outline-offset: 2px;
29	        }
30	
31	        button:focus-visible {
32	            outline: 3px solid #667eea;
33	            outline-offset: 2px;
34	        }
35	
36	        .skip-link {
37	            position: absolute;
38	            top: -40px;
39	            left: 0;
40	            background: #667eea;
41	            color: white;
42	            padding: 8px 16px;
43	            text-decoration: none;
44	            z-index: 100;
45	        }
46	
47	        .skip-link:focus {
48	            top: 0;
49	        }
50	
51	        header {
52	            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
53	            color: white;
54	            padding: 3rem 20px;
55	            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
56	        }
57	
58	        header h1 {
59	            max-width: 1200px;
60	            margin: 0 auto;
61	            font-size: 2.5rem;
62	            font-weight: 600;
63	        }
64	
65	        main {
66	            max-width: 1200px;
67	            margin: 0 auto;
68	            padding: 40px 20px;
69	        }
70	
71	        article {
72	            margin-bottom: 3rem;
73	        }
74	
75	        h2 {
76	            color: #667eea;
77	            margin-bottom: 1rem;
78	            font-size: 1.8rem;
79	        }
80	
81	        p {
82	            margin-bottom: 1rem;
83	            font-size: 1.05rem;
84	            line-height: 1.8;
85	        }
86	
87	        .cta-button {
88	            display: inline-block;
89	            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
90	            color: white;
91	            padding: 12px 32px;
92	            border: none;
93	            border-radius: 6px;
94	            font-size: 1rem;
95	            cursor: pointer;
96	            text-decoration: none;
97	            transition: transform 0.2s, box-shadow 0.2s;
98	        }
99	
100	        .cta-button:hover {
101	            transform: translateY(-2px);
102	            box-shadow: 0 8px 16px rgba(102, 126, 234, 0.4);
103	        }
104	
105	        .cta-button:active {
106	            transform: translateY(0);
107	        }
108	
109	        footer {
110	            background-color: #2c3e50;
111	            color: white;
112	            padding: 2rem 20px;
113	            text-align: center;
114	            margin-top: 3rem;
115	        }
116	
117	        footer p {
118	            margin: 0 0 1rem 0;
119	            font-size: 0.95rem;
120	            opacity: 0.8;
121	        }
122	
123	        footer a {
124	            color: #667eea;
125	            text-decoration: none;
126	        }
127	
128	        footer a:hover {
129	            text-decoration: underline;
130	        }
131	
132	        @media (max-width: 768px) {
133	            header h1 {
134	                font-size: 2rem;
135	            }
136	
137	            h2 {
138	                font-size: 1.5rem;
139	            }
140	
141	            p {
142	                font-size: 1rem;
143	            }
144	        }
145	    </style>
146	</head>
147	<body>
148	    <a href="#main-content" class="skip-link">Skip to main content</a>
149	
150	    <header>
151	        <h1>Welcome</h1>
152	    </header>
153	
154	    <main id="main-content">
155	        <article>
156	            <h2>Modern Web Template</h2>
157	            <p>This is an improved HTML template built with best practices for performance, accessibility, and maintainability.</p>
158	        </article>
159	
160	        <article>
161	            <h2>Key Features</h2>
162	            <p>
163	                This template includes semantic HTML elements, responsive design, modern CSS with gradients,
164	                proper meta tags for SEO, and accessibility considerations to create a solid foundation for any web project.
165	            </p>
166	            <ul style="margin-left: 20px; margin-bottom: 1rem;">
167	                <li>Semantic HTML5 structure</li>
168	                <li>WCAG 2.1 accessibility compliance</li>
169	                <li>Mobile-first responsive design</li>
170	                <li>Keyboard navigation support</li>
171	                <li>Open Graph meta tags</li>
172	            </ul>
173	        </article>
174	
175	        <article>
176	            <h2>Get Started</h2>
177	            <p>
178	                Use this template as a foundation for your next project. It's clean, well-structured, and ready to be
179	                customized to meet your specific needs.
180	            </p>
181	            <button class="cta-button">Learn More</button>
182	        </article>
183	    </main>
184	
185	    <footer>
186	        <p>&copy; 2026 Modern Web Template. All rights reserved.</p>
187	        <p>
188	            <a href="#privacy">Privacy Policy</a> |
189	            <a href="#terms">Terms of Service</a>
190	        </p>
191	    </footer>
192	
193	    <script type="application/ld+json">
194	    {
195	        "@context": "https://schema.org",
196	        "@type": "WebSite",
197	        "name": "Modern Web Template",
198	        "description": "A modern, accessible website built with best practices"
199	    }
200	    </script>
201	</body>
202	</html>
